function ELABORATE_POLYNOMIAL(monomials):
    total <- Const 0                       // empty-sum base case
    for (coeff, exps) in monomials:
        term <- Const 1                    // empty-product base case
        for i, d_i in enumerate(exps):
            repeat d_i times: term <- Mul(term, Var i)   // x_i^{d_i}
        total <- Add(total, Mul(Const coeff, term))
    return total

